<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class Contact extends Model { protected $fillable=['contact_code','name','mobile_1','mobile_2','email','organization_id','job_title','id_type','id_number','gender','religion','birth_date','contact_type_id','customer_identifier','product_id','remarks','present_address','present_location_id','permanent_address','permanent_location_id','father_name','mother_name','marital_status','spouse_name','marriage_date']; protected function casts():array{return ['birth_date'=>'date','marriage_date'=>'date'];} public function organization():BelongsTo{return $this->belongsTo(Organization::class,'organization_id');} public function product():BelongsTo{return $this->belongsTo(Product::class);} }
